static pthread_once_t once = PTHREAD_ONCE_INIT;
static resource_t *res;

static void acquire(void) { res = resource_open("cfg"); }

resource_t *get_resource(void) {
    pthread_once(&once, acquire);   /* returns only after acquire() completed */
    return res;                     /* NULL means the first acquisition failed */
}

